DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT105-S4-Q13$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$fails to provide an adequate definition of the word "messages"$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT105-S4-Q13 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT105-S4-Q13$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$infers that there is no extraterrestrial intelligence in neighboring star systems from the lack of proof that there is$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT105-S4-Q13 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT105-S4-Q13$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$assigns too little importance to the possibility that there is extraterrestrial intelligence beyond our neighboring star systems$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT105-S4-Q13 C'; END IF; END $guard$;
