INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT105-S4-Q13$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$There is no extraterrestrial intelligence in any neighboring star system.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Early television signals have reached those systems, and we have received no recognized response or other extraterrestrial message.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$Given no response, how could intelligence still exist there? Intelligent beings might not detect the transmissions, might not understand them, might choose not to answer, or their answer might not have reached us. No received message is a lack of proof of intelligence, not proof of its absence.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the move from “we have not established intelligence” to “there is none.”$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT105-S4-Q13$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$“Messages” has an ordinary role here: communications received from extraterrestrial origin. Defining it more tightly would not make silence prove the absence of intelligence.$batch01$), ($batch01$B$batch01$, $batch01$The argument infers that no neighboring system contains intelligence from our lack of evidence that one does. The missing responses have several possible explanations. Absence of proof is not automatically proof of absence.$batch01$), ($batch01$C$batch01$, $batch01$The conclusion concerns neighboring systems. Intelligence farther away is compatible with the conclusion and would not challenge it.$batch01$), ($batch01$D$batch01$, $batch01$The issue is whether anyone in neighboring systems is intelligent, not whether humans have also sent spacecraft recordings.$batch01$), ($batch01$E$batch01$, $batch01$Even if most systems are uninhabited, the conclusion says *none* of the neighboring systems has intelligence. A high general probability cannot establish that absolute claim from silence.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT105-S4-Q13$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
